}
function ellLabel(g, x, y, sub, size) {
  mkText(g, 'ℓ', x, y, size, { italic: true, anchor: 'start' });
  mkText(g, sub, x + size * 0.44, y + size * 0.30, size * 0.55, { italic: true, anchor: 'start' });
}
function drawArrow(g, x1, y1, x2, y2, color, w, headLen) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
  var grp = g.group();
  if (L < 2) return grp;
  var ux = dx / L, uy = dy / L, hl = headLen || 17, hw = (headLen ? headLen * 0.40 : 7);
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  grp.line(x1, y1, bx + ux * 2, by + uy * 2).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
  return grp;
}
function grayOf(a) { var v = Math.round(255 * a); return 'rgb(' + v + ',' + v + ',' + v + ')'; }
function redOf(a) { var v = Math.round(255 * (0.35 + 0.65 * a)); return 'rgb(' + v + ',0,0)'; }
function hoverable(el, tip, popTitle, popBody) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (popTitle) el.on('click', function () { showPopup(popTitle, popBody); });
  return el;
}

/* ── Static layer ─────────────────────────────────────────────────────────── */
var gStatic = FIGdraw.group();
var gDyn = FIGdraw.group();
var gMat = FIGdraw.group();

function buildStatic() {
  gStatic.clear();

  /* top index axis */
  gStatic.line(150, AX_Y, 786, AX_Y).stroke({ color: '#000', width: 2.6 });
  drawArrow(gStatic, 770, AX_Y, 800, AX_Y, '#000', 2.6, 16);
  for (var i = 0; i < NCELL; i++) {
    gStatic.line(xw(i), AX_Y - 2, xw(i), AX_Y + 19).stroke({ color: '#000', width: 2.4 });
  }
  mkText(gStatic, '0', xw(0), 26, 28);
  mkText(gStatic, '1', xw(1), 26, 28);
  mkText(gStatic, '2', xw(2), 26, 28);
  mkText(gStatic, '3', xw(3), 26, 28);
  mkText(gStatic, '\u22ef', xw(4) + 20, 26, 28);
  mkText(gStatic, '12', xw(12), 26, 28);
  mkText(gStatic, 'n', 812, 48, 30, { anchor: 'start' });

  /* scene bar outline + right label */
  gStatic.rect(NCELL * CW, SCENE_BOT - SCENE_TOP).move(SCENE_X0, SCENE_TOP)
    .fill('none').stroke({ color: '#000', width: 5 });
  ellLabel(gStatic, 103, 95, 'w', 44);
  mkText(gStatic, 'Scene', 828, 99, 34, { anchor: 'start' });

  /* occluder */
  var segA = gStatic.rect(PX - GAP - OCC_L, OCC_H).move(OCC_L, OCC_Y).fill('#000');
  var segB = gStatic.rect(OCC_R - (PX + GAP), OCC_H).move(PX + GAP, OCC_Y).fill('#000');
  var occTip = 'Opaque occluder — absorbs every ray except the ones hitting the gap';
  hoverable(segA, occTip, 'Occluder',
    'The occluder is an opaque wall. Of the infinitely many rays leaving one scene patch, it absorbs all but the single ray aimed at the pinhole, which is exactly what makes the scene→sensor map one-to-one.');
  hoverable(segB, occTip, 'Occluder',
    'The occluder is an opaque wall. Of the infinitely many rays leaving one scene patch, it absorbs all but the single ray aimed at the pinhole, which is exactly what makes the scene→sensor map one-to-one.');
  mkText(gStatic, 'Occluder', 152, OCC_CY, 32, { anchor: 'end' });
  mkText(gStatic, 'Aperture', 790, OCC_CY, 32, { anchor: 'start' });

  /* pinhole annotation */
  drawArrow(gStatic, 618, 464, 529, 421, '#000', 3, 18);
  mkText(gStatic, 'Pinhole', 628, 478, 32, { anchor: 'start' });
  var hole = gStatic.rect(2 * GAP, OCC_H + 16).move(PX - GAP, OCC_Y - 8).fill('#fff').opacity(0.001);
  hoverable(hole, 'Pinhole: the only opening in the occluder', 'Pinhole',
    'Every ray that reaches the sensor must pass through this one point. Because all admitted rays cross here, light from the left of the scene lands on the right of the sensor — the image is index-reversed.');

  /* sensor bar outline + labels */
  gStatic.rect(NCELL * CS, SENS_H).move(SENS_X0, SENS_TOP)
    .fill('none').stroke({ color: '#000', width: 3 });
  ellLabel(gStatic, 320, 582, 's', 40);
  mkText(gStatic, 'Camera sensor', 742, 586, 30, { anchor: 'start' });
}

/* ── Dynamic layer ────────────────────────────────────────────────────────── */
function buildDynamic() {
  gDyn.clear();

  /* scene cells */
  for (var i = 0; i < NCELL; i++) {
    (function (i) {
      var sel = (i === state.n);
      var r = gDyn.rect(CW, SCENE_BOT - SCENE_TOP).move(xw(i) - CW / 2, SCENE_TOP)
        .fill(sel ? redOf(state.albedo[i]) : grayOf(state.albedo[i]))
        .stroke({ color: '#000', width: 3.2 });
      r.css('cursor', 'ns-resize');
      r.on('mousemove', function (e) {
        showTooltip('Scene patch n = ' + i + ' · albedo ' + state.albedo[i].toFixed(2) +
          (sel ? ' (selected)' : '') + ' — click to select, drag up/down to change brightness', e);
      });
      r.on('mouseleave', function () { hideTooltip(); });
      r.on('mousedown', function (e) {
        e.preventDefault();
        FIGdrag = { i: i, y0: e.clientY, a0: state.albedo[i], moved: false };
      });
    })(i);
  }

  /* ray fan */
  var S = { x: xw(state.n), y: SCENE_BOT };
  var angles = [-72, -58, -40, -18, 0, 20, 52, 63];
  for (var k = 0; k < angles.length; k++) {
    var a = angles[k] * Math.PI / 180, sx = Math.sin(a), cy = Math.cos(a);
    var tOcc = (OCC_Y - S.y) / cy;
    var hx = S.x + tOcc * sx;
    if (hx > PX - GAP && hx < PX + GAP) continue;           // duplicate of pinhole ray
    var blocked = (hx >= OCC_L && hx <= PX - GAP) || (hx >= PX + GAP && hx <= OCC_R);
    var ex, ey;
    if (blocked) { ex = hx; ey = OCC_Y; }
    else {
      var t = 430;
      if (sx < -1e-6) t = Math.min(t, (35 - S.x) / sx);
      if (sx > 1e-6) t = Math.min(t, (962 - S.x) / sx);
      t = Math.min(t, (532 - S.y) / cy);
      ex = S.x + t * sx; ey = S.y + t * cy;
    }
    var g = drawArrow(gDyn, S.x, S.y, ex, ey, '#ff0000', 4);
    hoverable(g, blocked ? 'This ray is absorbed by the occluder'
                         : 'This ray misses the aperture entirely — it never reaches the sensor');
  }

  /* the one admitted ray */
  var tgt = PX + (RAY_TIP_Y - OCC_CY) / (OCC_CY - S.y) * (PX - S.x);
  var pr = drawArrow(gDyn, S.x, S.y, tgt, RAY_TIP_Y, '#ff0000', 4.2);
  var sIdx = state.reversed ? state.n : 12 - state.n;
  hoverable(pr, 'The single admitted ray: scene n = ' + state.n + ' → sensor index ' + sIdx,
    'One ray, one pixel',
    'Exactly one ray from scene patch n = ' + state.n + ' threads the pinhole and lands on one sensor cell. ' +
    'Repeat this for all 13 patches and you get 13 independent ray paths — that is why the camera is a linear, one-to-one map.');
  gDyn.circle(10).center(S.x, S.y).fill('#ff0000');

  /* sensor cells: cell k reads scene patch 12-k */
  for (var m = 0; m < NCELL; m++) {
    (function (m) {
      var src = 12 - m;
      var sel = (src === state.n);
      var r = gDyn.rect(CS, SENS_H).move(xs(m) - CS / 2, SENS_TOP)
        .fill(sel ? redOf(state.albedo[src]) : grayOf(state.albedo[src]))
        .stroke({ color: '#000', width: 2 });
      hoverable(r, 'Sensor cell at physical position ' + m + ' · reads scene patch ' + src +
        ' · value ' + state.albedo[src].toFixed(2), 'Sensor cell',
        'This cell can only see scene patch ' + src + ', because that is the one patch whose ray through the pinhole lands here. ' +
        'Its value equals that patch\'s albedo exactly — no mixing, no blur.');
    })(m);
  }

  /* bottom (sensor) index axis */
  gDyn.line(372, SAX_Y, 724, SAX_Y).stroke({ color: '#000', width: 2.4 });
  for (var q = 0; q < NCELL; q++) {
    gDyn.line(xs(q), SAX_Y - 9, xs(q), SAX_Y + 10).stroke({ color: '#000', width: 2.2 });
  }
  if (state.reversed) {
    drawArrow(gDyn, 392, SAX_Y, 360, SAX_Y, '#000', 2.4, 16);
    mkText(gDyn, 'n', 336, SAX_Y + 8, 30, { anchor: 'end' });
  } else {
    drawArrow(gDyn, 704, SAX_Y, 736, SAX_Y, '#000', 2.4, 16);
    mkText(gDyn, 'n', 748, SAX_Y + 8, 30, { anchor: 'start' });
  }
  var leftLab = state.reversed ? '12' : '0';
  var rightLab = state.reversed ? '0' : '12';
  var selPos = 12 - state.n;                               // physical cell holding the red pixel
  var selLab = String(state.reversed ? state.n : 12 - state.n);
  if (selPos !== 0) mkText(gDyn, leftLab, xs(0), SAX_Y + 34, 26);
  if (selPos !== 12) mkText(gDyn, rightLab, xs(12), SAX_Y + 34, 26);
  mkText(gDyn, selLab, xs(selPos), SAX_Y + 34, 26, { fill: '#ff0000', weight: 'bold', halo: 3.5 });
}

/* ── Matrix overlay ───────────────────────────────────────────────────────── */
var matKey = '';
function buildMatrix() {
  var key = state.matrix + '|' + state.n;
  if (key === matKey) return;
  matKey = key;
  gMat.clear();
  if (!state.matrix) return;
  var W = NCELL * MC, H = NCELL * MC;
  gMat.rect(W + 20, H + 20).move(MX - 10, MY - 10).fill('#ffffff').opacity(0.92).stroke('none');
  for (var r = 0; r < NCELL; r++) {
    for (var c = 0; c < NCELL; c++) {
      var one = (r === 12 - c);
      var x = MX + c * MC, y = MY + r * MC;
      if (one && c === state.n) gMat.rect(MC, MC).move(x, y).fill('#ffd6d6').stroke('none');
      gMat.rect(MC, MC).move(x, y).fill('none').stroke({ color: '#e2e2e2', width: 0.5 });
      mkText(gMat, one ? '1' : '0', x + MC / 2, y + MC / 2 + 0.5,
        one ? 11 : 9,
        { fill: one ? (c === state.n ? '#ff0000' : '#000') : '#c2c2c2',
          weight: one ? 'bold' : 'normal' });
    }
  }
  /* brackets */
  gMat.polyline([[MX - 7, MY - 5], [MX - 13, MY - 5], [MX - 13, MY + H + 5], [MX - 7, MY + H + 5]])
    .fill('none').stroke({ color: '#000', width: 2 });
  gMat.polyline([[MX + W + 7, MY - 5], [MX + W + 13, MY - 5], [MX + W + 13, MY + H + 5], [MX + W + 7, MY + H + 5]])
    .fill('none').stroke({ color: '#000', width: 2 });
  /* caption  ℓs = A ℓw */
  var cx = MX + 18;
  mkText(gMat, 'ℓ', cx, MY - 32, 26, { italic: true, anchor: 'start' });
  mkText(gMat, 's', cx + 12, MY - 24, 15, { italic: true, anchor: 'start' });
  mkText(gMat, '=', cx + 32, MY - 32, 26, { anchor: 'start' });
  mkText(gMat, 'A', cx + 56, MY - 32, 26, { italic: true, anchor: 'start' });
  mkText(gMat, 'ℓ', cx + 84, MY - 32, 26, { italic: true, anchor: 'start' });
  mkText(gMat, 'w', cx + 96, MY - 24, 15, { italic: true, anchor: 'start' });
  var hit = gMat.rect(W + 26, H + 60).move(MX - 13, MY - 46).fill('#fff').opacity(0.001);
  hoverable(hit, 'A is a 13×13 permutation matrix with 1s on the anti-diagonal',
    'The camera as a matrix',
    'Stacking the 13 ray relations gives ℓs = A ℓw. For an ideal pinhole, A has a 1 in entry (12−n, n) and 0 everywhere else: a pure coordinate reversal. The whole optical system is one linear map.');
}

/* ── Render + state plumbing ──────────────────────────────────────────────── */
function render() {
  buildDynamic();
  buildMatrix();
  var el = document.getElementById('mapReadout');
  if (el) {
    el.textContent = 'scene n = ' + state.n + '  →  sensor index ' +
      (state.reversed ? state.n : 12 - state.n) +
      '  (cell ' + (12 - state.n) + ' from the left)';
  }
}
function setN(i) {
  state.n = Math.max(0, Math.min(12, i));
  var s = document.getElementById('selectScenePixelInput');
  var o = document.getElementById('selectScenePixelVal');
  if (s) s.value = state.n;
  if (o) o.value = state.n;
  render();
}
function update_selectScenePixel(v) { state.n = v; render(); }
function toggle_sensorAxisOrientation(on) { state.reversed = on; render(); }
function toggle_viewMode(on) { state.matrix = on; render(); }
function trigger_dragAlbedo() { state.albedo = PATTERN.slice(); render(); }
function trigger_resetAlbedo() { state.albedo = PATTERN.map(function () { return 1; }); render(); }

/* drag-to-change-albedo */
var FIGdrag = null;
document.addEventListener('mousemove', function (e) {
  if (!FIGdrag) return;
  var dy = FIGdrag.y0 - e.clientY;
  if (Math.abs(dy) > 3) FIGdrag.moved = true;
  var a = Math.max(0, Math.min(1, FIGdrag.a0 + dy / 160));
  state.albedo[FIGdrag.i] = a;
  render();
});
document.addEventListener('mouseup', function () {
  if (!FIGdrag) return;
  if (!FIGdrag.moved) setN(FIGdrag.i);
  FIGdrag = null;
});

