  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy);
  var grp = g.group();
  if (L < 2) return grp;
  var ux = dx / L, uy = dy / L, hl = headLen || 19, hw = (headLen ? headLen * 0.42 : 8);
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  grp.line(x1, y1, bx + ux * 2, by + uy * 2).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
  return grp;
}
function grayOf(a) { var v = Math.round(255 * a); return 'rgb(' + v + ',' + v + ',' + v + ')'; }
function redOf(a) { var v = Math.round(240 * (0.35 + 0.65 * a)); return 'rgb(' + v + ',0,0)'; }
function hoverable(el, tip, popTitle, popBody) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (popTitle) el.on('click', function () { showPopup(popTitle, popBody); });
  return el;
}

/* ── Layers ───────────────────────────────────────────────────────────────── */
var gStatic = FIGdraw.group();
var gDyn = FIGdraw.group();
var gMat = FIGdraw.group();

/* ── Static layer ─────────────────────────────────────────────────────────── */
function buildStatic() {
  gStatic.clear();

  /* top index axis */
  gStatic.line(149, AX_Y, 712, AX_Y).stroke({ color: '#000', width: 2.6 });
  drawArrow(gStatic, 700, AX_Y, 735, AX_Y, '#000', 2.6, 17);
  for (var i = 0; i < NCELL; i++) {
    gStatic.line(xw(i), AX_Y - 4, xw(i), AX_Y + 18).stroke({ color: '#000', width: 2.4 });
  }
  mkText(gStatic, '0', xw(0), 29, 30);
  mkText(gStatic, '1', xw(1), 29, 30);
  mkText(gStatic, '2', xw(2), 29, 30);
  mkText(gStatic, '3', xw(3), 29, 30);
  mkText(gStatic, '\u22ef', xw(4) + 16, 29, 30);
  mkText(gStatic, '12', xw(12), 29, 30);
  mkText(gStatic, 'n', 744, 46, 30, { anchor: 'start' });

  /* labels flanking the three tiers */
  ellLabel(gStatic, 88, 107, 'w', 46);
  mkText(gStatic, 'Scene', RIGHT_LAB_X, 106, 31, { anchor: 'start' });

  /* occluder (two thick segments with the pinhole gap between them) */
  var segA = gStatic.rect(PX - GAP - OCC_L, OCC_H).move(OCC_L, OCC_Y).fill('#000');
  var segB = gStatic.rect(OCC_R - (PX + GAP), OCC_H).move(PX + GAP, OCC_Y).fill('#000');
  var occTip = 'Opaque occluder — absorbs every ray except the one hitting the gap';
  var occBody = 'The occluder is an opaque wall. Of the infinitely many rays leaving one scene patch, it absorbs all but the single ray aimed at the pinhole, which is exactly what makes the scene→sensor map one-to-one.';
  hoverable(segA, occTip, 'Occluder', occBody);
  hoverable(segB, occTip, 'Occluder', occBody);
  mkText(gStatic, 'Occluder', 156, OCC_CY, 30, { anchor: 'end', halo: 4 });
  mkText(gStatic, 'Aperture', RIGHT_LAB_X, OCC_CY, 31, { anchor: 'start', halo: 4 });

  /* pinhole annotation (kept to the right of the transmitted ray) */
  drawArrow(gStatic, 507, 470, 448, 437, '#000', 2.8, 18);
  mkText(gStatic, 'Pinhole', 514, 482, 31, { anchor: 'start', halo: 4 });
  var hole = gStatic.rect(2 * GAP + 8, OCC_H + 18).move(PX - GAP - 4, OCC_Y - 9).fill('#fff').opacity(0.001);
  hoverable(hole, 'Pinhole: the only opening in the occluder', 'Pinhole',
    'Every ray that reaches the sensor must pass through this one point. Because all admitted rays cross here, light from the left of the scene lands on the right of the sensor — the image is index-reversed.');

  ellLabel(gStatic, 200, 611, 's', 42);
  mkText(gStatic, 'Camera sensor', RIGHT_LAB_X, 611, 30, { anchor: 'start' });
}

/* ── Ray fan geometry ─────────────────────────────────────────────────────── */
var FAN_ANGLES = [-60, -39, -23, -1, 13, 44, 65];   /* degrees from straight down */

function escapeLength(sx, cy, Sx, Sy) {
  var t = 1e9;
  if (sx < -1e-6) t = Math.min(t, (130 - Sx) / sx);
  if (sx > 1e-6) t = Math.min(t, (720 - Sx) / sx);
  t = Math.min(t, (395 - Sy) / cy);
  t = Math.max(t, 150);
  var tf = 1e9;
  if (sx < -1e-6) tf = Math.min(tf, (28 - Sx) / sx);
  if (sx > 1e-6) tf = Math.min(tf, (960 - Sx) / sx);
  tf = Math.min(tf, (402 - Sy) / cy);
  return Math.min(t, tf);
}

/* ── Dynamic layer ────────────────────────────────────────────────────────── */
function buildDynamic() {
  gDyn.clear();

  /* ── scene bar: cell fills (interactive) ── */
  for (var i = 0; i < NCELL; i++) {
    (function (i) {
      var sel = (i === state.n);
      var r = gDyn.rect(CW, SCENE_BOT - SCENE_TOP).move(xw(i) - CW / 2, SCENE_TOP)
        .fill(sel ? redOf(state.albedo[i]) : grayOf(state.albedo[i])).stroke('none');
      r.css('cursor', 'ns-resize');
      r.on('mousemove', function (e) {
        showTooltip('Scene patch n = ' + i + ' · albedo ' + state.albedo[i].toFixed(2) +
          (sel ? ' (selected)' : '') + ' — click to select, drag up/down to change brightness', e);
      });
      r.on('mouseleave', function () { hideTooltip(); });
      r.on('mousedown', function (e) {
        e.preventDefault();
        FIGdrag = { i: i, y0: e.clientY, a0: state.albedo[i], moved: false };
      });
    })(i);
  }
  /* thin internal dividers + one heavy outer enclosure */
  var gBar = gDyn.group().css('pointer-events', 'none');
  for (var d = 1; d < NCELL; d++) {
    gBar.line(SCENE_X0 + d * CW, SCENE_TOP, SCENE_X0 + d * CW, SCENE_BOT)
      .stroke({ color: '#000', width: 2.4 });
  }
  gBar.rect(NCELL * CW, SCENE_BOT - SCENE_TOP).move(SCENE_X0, SCENE_TOP)
    .fill('none').stroke({ color: '#000', width: 5.5 });

  /* ── ray fan from the selected patch ── */
  var S = { x: xw(state.n), y: SCENE_BOT };
  for (var k = 0; k < FAN_ANGLES.length; k++) {
    var a = FAN_ANGLES[k] * Math.PI / 180, sx = Math.sin(a), cy = Math.cos(a);
    var tOcc = (OCC_Y - S.y) / cy;
    var hx = S.x + tOcc * sx;
    if (hx > PX - GAP && hx < PX + GAP) continue;                       /* that is the admitted ray */
    var blocked = (hx >= OCC_L && hx <= OCC_R);
    var ex, ey;
    if (blocked) { ex = hx; ey = OCC_Y; }
    else { var t = escapeLength(sx, cy, S.x, S.y); ex = S.x + t * sx; ey = S.y + t * cy; }
    var g = drawArrow(gDyn, S.x, S.y, ex, ey, RED, 4);
    hoverable(g, blocked ? 'This ray is absorbed by the occluder'
                         : 'This ray misses the occluder entirely — it never reaches the sensor');
  }

  /* ── the single admitted ray ── */
  var tgt = xs(12 - state.n);                                            /* exact perspective target */
  var pr = drawArrow(gDyn, S.x, S.y, tgt, RAY_TIP_Y, RED, 4.2);
  var sIdx = state.reversed ? state.n : 12 - state.n;
  hoverable(pr, 'The single admitted ray: scene n = ' + state.n + ' → sensor index ' + sIdx,
    'One ray, one pixel',
    'Exactly one ray from scene patch n = ' + state.n + ' threads the pinhole and lands on one sensor cell. ' +
    'Repeat this for all 13 patches and you get 13 independent ray paths — that is why the camera is a linear, one-to-one map.');
  gDyn.circle(10).center(S.x, S.y).fill(RED);

  /* ── sensor bar: cell k reads scene patch 12−k ── */
  for (var m = 0; m < NCELL; m++) {
    (function (m) {
      var src = 12 - m;
      var sel = (src === state.n);
      var r = gDyn.rect(CS, SENS_H).move(xs(m) - CS / 2, SENS_TOP)
        .fill(sel ? redOf(state.albedo[src]) : grayOf(state.albedo[src])).stroke('none');
      hoverable(r, 'Sensor cell at physical position ' + m + ' · reads scene patch ' + src +
        ' · value ' + state.albedo[src].toFixed(2), 'Sensor cell',
        'This cell can only see scene patch ' + src + ', because that is the one patch whose ray through the pinhole lands here. ' +
        'Its value equals that patch\'s albedo exactly — no mixing, no blur.');
    })(m);
  }
  var gSen = gDyn.group().css('pointer-events', 'none');
  for (var e2 = 1; e2 < NCELL; e2++) {
    gSen.line(SENS_X0 + e2 * CS, SENS_TOP, SENS_X0 + e2 * CS, SENS_TOP + SENS_H)
      .stroke({ color: '#000', width: 1.6 });
  }
  gSen.rect(NCELL * CS, SENS_H).move(SENS_X0, SENS_TOP)
    .fill('none').stroke({ color: '#000', width: 3.2 });

  /* ── bottom (sensor) index axis ── */
  var gAx = gDyn.group().css('pointer-events', 'none');
  gAx.line(262, SAX_Y, 600, SAX_Y).stroke({ color: '#000', width: 2.4 });
  for (var q = 0; q < NCELL; q++) {
    gAx.line(xs(q), SAX_Y - 10, xs(q), SAX_Y + 10).stroke({ color: '#000', width: 2.2 });
  }
  if (state.reversed) {
    drawArrow(gAx, 272, SAX_Y, 240, SAX_Y, '#000', 2.4, 17);
    mkText(gAx, 'n', 228, SAX_Y + 9, 29, { anchor: 'end' });
  } else {
    drawArrow(gAx, 590, SAX_Y, 622, SAX_Y, '#000', 2.4, 17);
    mkText(gAx, 'n', 632, SAX_Y + 9, 29, { anchor: 'start' });
  }
  var leftLab = state.reversed ? '12' : '0';
  var rightLab = state.reversed ? '0' : '12';
  var selPos = 12 - state.n;                                             /* physical cell of the red pixel */
  var selLab = String(state.reversed ? state.n : 12 - state.n);
  if (selPos !== 0) mkText(gAx, leftLab, xs(0), SAX_Y + 36, 28);
  if (selPos !== 12) mkText(gAx, rightLab, xs(12), SAX_Y + 36, 28);
  mkText(gAx, selLab, xs(selPos), SAX_Y + 36, 28, { fill: RED, weight: 'bold', halo: 4 });
}

/* ── Matrix overlay ───────────────────────────────────────────────────────── */
var matKey = '';
function buildMatrix() {
  var key = state.matrix + '|' + state.n;
  if (key === matKey) return;
  matKey = key;
  gMat.clear();
  if (!state.matrix) return;
  var W = NCELL * MC, H = NCELL * MC;
  gMat.rect(W + 24, H + 24).move(MX - 12, MY - 12).fill('#ffffff').opacity(0.94).stroke('none');
  for (var r = 0; r < NCELL; r++) {
    for (var c = 0; c < NCELL; c++) {
      var one = (r === 12 - c);
      var x = MX + c * MC, y = MY + r * MC;
      if (one && c === state.n) gMat.rect(MC, MC).move(x, y).fill('#ffd6d6').stroke('none');
      gMat.rect(MC, MC).move(x, y).fill('none').stroke({ color: '#e4e4e4', width: 0.5 });
      mkText(gMat, one ? '1' : '0', x + MC / 2, y + MC / 2 + 0.5, one ? 11.5 : 9,
        { fill: one ? (c === state.n ? RED : '#000') : '#c2c2c2',
          weight: one ? 'bold' : 'normal' });
    }
  }
  gMat.polyline([[MX - 8, MY - 6], [MX - 14, MY - 6], [MX - 14, MY + H + 6], [MX - 8, MY + H + 6]])
    .fill('none').stroke({ color: '#000', width: 2 });
  gMat.polyline([[MX + W + 8, MY - 6], [MX + W + 14, MY - 6], [MX + W + 14, MY + H + 6], [MX + W + 8, MY + H + 6]])
    .fill('none').stroke({ color: '#000', width: 2 });
  var cx = MX + 16;
  mkText(gMat, 'ℓ', cx, MY - 34, 26, { italic: true, anchor: 'start', weight: 'bold' });
  mkText(gMat, 's', cx + 13, MY - 26, 15, { italic: true, anchor: 'start' });
  mkText(gMat, '=', cx + 34, MY - 34, 26, { anchor: 'start' });
  mkText(gMat, 'A', cx + 58, MY - 34, 26, { italic: true, anchor: 'start' });
  mkText(gMat, 'ℓ', cx + 88, MY - 34, 26, { italic: true, anchor: 'start', weight: 'bold' });
  mkText(gMat, 'w', cx + 101, MY - 26, 15, { italic: true, anchor: 'start' });
  var hit = gMat.rect(W + 30, H + 62).move(MX - 15, MY - 48).fill('#fff').opacity(0.001);
  hoverable(hit, 'A is a 13×13 permutation matrix with 1s on the anti-diagonal',
    'The camera as a matrix',
    'Stacking the 13 ray relations gives ℓs = A ℓw. For an ideal pinhole, A has a 1 in entry (12−n, n) and 0 everywhere else: a pure coordinate reversal. The whole optical system is one linear map.');
}

/* ── Render + state plumbing ──────────────────────────────────────────────── */
function render() {
  buildDynamic();
  buildMatrix();
  var el = document.getElementById('mapReadout');
  if (el) {
    el.textContent = 'scene n = ' + state.n + '  →  sensor index ' +
      (state.reversed ? state.n : 12 - state.n) +
      '  (cell ' + (12 - state.n) + ' from the left)';
  }
}
function setN(i) {
  state.n = Math.max(0, Math.min(12, i));
  var s = document.getElementById('selectScenePixelInput');
  var o = document.getElementById('selectScenePixelVal');
  if (s) s.value = state.n;
  if (o) o.value = state.n;
  render();
}
function update_selectScenePixel(v) { state.n = v; render(); }
function toggle_sensorAxisOrientation(on) { state.reversed = on; render(); }
function toggle_viewMode(on) { state.matrix = on; render(); }
function trigger_dragAlbedo() { state.albedo = PATTERN.slice(); render(); }
function trigger_resetAlbedo() { state.albedo = PATTERN.map(function () { return 1; }); render(); }

/* drag-to-change-albedo */
var FIGdrag = null;
document.addEventListener('mousemove', function (e) {
  if (!FIGdrag) return;
  var dy = FIGdrag.y0 - e.clientY;
  if (Math.abs(dy) > 3) FIGdrag.moved = true;
  var a = Math.max(0, Math.min(1, FIGdrag.a0 + dy / 160));
  state.albedo[FIGdrag.i] = a;
  render();
});
document.addEventListener('mouseup', function () {
  if (!FIGdrag) return;
  if (!FIGdrag.moved) setN(FIGdrag.i);
  FIGdrag = null;
});

/* ── Demo steps ───────────────────────────────────────────────────────────── */
var FIGsteps = [
  { title: 'The flatland scene',
    narration: 'The scene is a 1D row of 13 patches indexed n = 0 … 12, each with its own brightness, collected into the vector ℓw. Below it sits an opaque occluder with a single pinhole, and below that the camera sensor ℓs.',
    state: { n: 2, reversed: true, matrix: false, pattern: false } },
  { title: 'One point, many rays, one survivor',
    narration: 'Scene patch n = 2 radiates light in every direction, but the occluder blocks almost all of it. Exactly one ray threads the pinhole and strikes a single sensor cell. Click any other cell to move the source.',
    state: { n: 2, reversed: true, matrix: false, pattern: false } },
  { title: 'Rays cross, so the image flips',
    narration: 'Because every admitted ray passes through the same tiny hole, light from the left of the scene lands on the right of the sensor. With the axis "aligned with scene" the landing index reads 10, not 2 — which is why the physical sensor axis is drawn pointing left.',
    state: { n: 2, reversed: false, matrix: false, pattern: false } },
  { title: 'Paint the scene, read the sensor',
    narration: 'Now the scene carries a grayscale albedo pattern. Drag any scene cell up or down: exactly one sensor value moves, by the same amount — no mixing, no blurring. The camera is acting as a linear operator.',
    state: { n: 5, reversed: true, matrix: false, pattern: true } },
  { title: 'The camera as a matrix',
    narration: 'This ideal pinhole camera is ℓs = A ℓw, where A is a permutation matrix with 1s along the anti-diagonal — the entire optical system written as one linear map.',
    state: { n: 2, reversed: true, matrix: true, pattern: true } }
];
var FIGstep = 0;
function applyStepState(s) {
  if (s.n != null) {
    state.n = s.n;
    var sl = document.getElementById('selectScenePixelInput');
    var ov = document.getElementById('selectScenePixelVal');
    if (sl) sl.value = s.n;
    if (ov) ov.value = s.n;
  }
  if (s.reversed != null) {
    state.reversed = s.reversed;
    var c1 = document.getElementById('sensorAxisOrientationInput');
    if (c1) c1.checked = s.reversed;
  }
  if (s.matrix != null) {
    state.matrix = s.matrix;
    var c2 = document.getElementById('viewModeInput');
    if (c2) c2.checked = s.matrix;
  }
  if (s.pattern != null) {
    state.albedo = s.pattern ? PATTERN.slice() : PATTERN.map(function () { return 1; });
  }
  render();
}
function showStep(i) {
  FIGstep = (i + FIGsteps.length) % FIGsteps.length;
  var st = FIGsteps[FIGstep];
  applyStepState(st.state);
  var t = document.getElementById('stepTitle');
  var nrt = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (t) t.textContent = st.title;
  if (nrt) nrt.textContent = st.narration;
  if (lab) lab.textContent = 'Step ' + (FIGstep + 1) + ' / ' + FIGsteps.length;
}
function nextStep() { showStep(FIGstep + 1); }
function prevStep() { showStep(FIGstep - 1); }

/* ── Boot ─────────────────────────────────────────────────────────────────── */
buildStatic();
showStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In flatland, a pinhole camera maps a 1D scene of intensities to a 1D sensor reading by letting exactly one ray per scene point through the aperture, producing a reversed (index-flipped) copy of the scene — a linear map from the world vector ℓ_w to the sensor vector ℓ_s.
KEY INSIGHT (what students should walk away understanding): A pinhole camera is nothing more exotic than a linear map from the scene vector to the sensor vector — and for an ideal pinhole that map is just a coordinate reversal, an anti-diagonal matrix.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "In flatland, a pinhole camera maps a 1D scene of intensities to a 1D sensor reading by letting exactly one ray per scene point through the aperture, producing a reversed (index-flipped) copy of the scene — a linear map from the world vector ℓ_w to the sensor vector ℓ_s.",
  "figureType": "diagram",
  "elements": [
    "Top horizontal index axis labeled 'n' with tick marks and labels 0, 1, 2, 3, '…', 12, arrowhead pointing right",
    "Scene bar: horizontal row of 13 equal square cells with thick black outlines, labeled ℓ_w on the left in script italic, labeled 'Scene' on the right",
    "One highlighted scene cell (default n = 2) filled solid red",
    "Fan of red arrows emanating downward from the highlighted scene cell in many directions: several missing the occluder entirely (pointing off to the left and right), several terminating on the black occluder bar, and exactly one passing through the pinhole gap",
    "Occluder: thick solid black horizontal bar split into two segments with a small gap between them; label 'Occluder' on the left, label 'Aperture' on the right",
    "Pinhole: the gap between the two occluder segments, indicated by a short black arrow annotation labeled 'Pinhole'",
    "The single transmitted red ray continuing from the pinhole down-left to the sensor, ending in an arrowhead on one sensor cell",
    "Sensor bar: horizontal row of 13 equal cells with thinner outlines, labeled ℓ_s on the left in script italic, labeled 'Camera sensor' on the right",
    "One highlighted sensor cell (default index 2 in sensor coordinates, i.e., near the right end) filled solid red",
    "Bottom index axis below the sensor with tick marks, arrowhead pointing LEFT, label 'n' at the left end, tick labels 12 (left), 2 and 0 (right) showing the reversed ordering",
    "Optional overlay panel: the linear-system statement ℓ_s = A ℓ_w with A drawn as an anti-diagonal (flip) matrix of 0s and 1s",
    "Albedo/intensity shading of scene cells (grayscale fill proportional to intensity) and matching shading on the sensor cells"
  ],
  "interactions": [
    {
      "id": "selectScenePixel",
      "type": "click",
      "teaches": "Each scene point emits rays in all directions, but the pinhole admits exactly one of them, so scene index n lands on one and only one sensor cell — the geometric core of the pinhole mapping."
    },
    {
      "id": "dragAlbedo",
      "type": "drag",
      "teaches": "Dragging the intensity (albedo) of any scene cell changes only the corresponding sensor cell, and proportionally — the mapping is both one-to-one and linear, not just a picture of rays."
    },
    {
      "id": "sensorAxisOrientation",
      "type": "toggle",
      "label": "Sensor index direction",
      "options": [
        "Reversed (physical)",
        "Aligned with scene"
      ],
      "default": "Reversed (physical)",
      "teaches": "The sensor axis must run opposite to the scene axis because rays cross at the pinhole; 'flipping' the axis is a bookkeeping choice, not a change to the physics.",
      "...": ""
    },
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "View",
      "options": [
        "Ray diagram",
        "Ray diagram + matrix"
      ],
      "default": "Ray diagram",
      "teaches": "The whole ray picture collapses into a single matrix A whose anti-diagonal of 1s is exactly the coordinate reversal, so ℓ_s = A ℓ_w."
    }
  ],
  "demo_steps": [
    {
      "title": "The flatland scene",
      "narration": "The scene is a 1D row of 13 patches indexed n = 0 … 12, each with its own brightness, collected into the vector ℓ_w. Below it sits an opaque occluder with a single pinhole, and below that the camera sensor ℓ_s.",
      "state": {
        "viewMode": "Ray diagram",
        "sensorAxisOrientation": "Reversed (physical)"
      }
    },
    {
      "title": "One point, many rays, one survivor",
      "narration": "Click scene patch n = 2: it radiates light in every direction, but the occluder blocks almost all of it. Exactly one ray threads the pinhole and strikes a single sensor cell.",
      "state": {
        "viewMode": "Ray diagram",
        "sensorAxisOrientation": "Reversed (physical)"
      }
    },
    {
      "title": "Rays cross, so the image flips",
      "narration": "Because every admitted ray passes through the same tiny hole, light from the left of the scene lands on the right of the sensor. Switch the sensor index direction and watch patch 2 sit at sensor index 2 again — the reversal is why the sensor axis is drawn pointing left.",
      "state": {
        "viewMode": "Ray diagram",
        "sensorAxisOrientation": "Aligned with scene"
      }
    },
    {
      "title": "Paint the scene, read the sensor",
      "narration": "Drag the brightness of several scene patches. Each edit moves exactly one sensor value, by the same amount — no mixing, no blurring. The camera is acting as a linear operator.",
      "state": {
        "viewMode": "Ray diagram",
        "sensorAxisOrientation": "Reversed (physical)"
      }
    },
    {
      "title": "The camera as a matrix",
      "narration": "Reveal the matrix view: this ideal pinhole camera is ℓ_s = A ℓ_w where A is a permutation matrix with 1s along the anti-diagonal — the entire optical system written as one linear map.",
      "state": {
        "viewMode": "Ray diagram + matrix",
        "sensorAxisOrientation": "Reversed (physical)"
      }
    }
